function renderFooter(){$('#footerCounts').textContent=tasks.filter(t=>t.status==='Downloading').length+' active · '+tasks.filter(t=>t.status==='Waiting').length+' waiting';const total=tasks.reduce((n,t)=>n+t.speed,0);$('#totalSpeed').textContent=fmtSpeed(speedLimit?Math.min(total,speedLimit):total);$('#speedButton').innerHTML=esc(speedMode)+(speedLimit?' · '+speedLimit+' MB/s':'')+ico('chevron-down');}
function renderDetails(){const items=chosen();$('#details').hidden=!showDetails||!items.length||page!=='downloads'||contextMenuState.suppressDetails;if(!items.length)return;const t=items[0],allComplete=items.every(v=>v.status==='Completed');const actions=`<div class="details-actions">${btn('Open file','file','open',items.length!==1||!allComplete?'disabled':'')}${btn('Open folder','folder','folder',items.length!==1?'disabled':'')}<button id="detailsMore" class="secondary">${ico('more')}More</button><button id="collapseDetails" class="details-close" title="Hide details panel" aria-label="Hide details panel">${ico('close')}</button></div>`;if(items.length>1){$('#detailsContent').innerHTML=actions+`<div class="details-file">${ico('file')}<strong>${items.length} transfers selected</strong></div><div class="detail-cards"><section class="detail-card"><h3>Selection</h3><dl><dt>Total</dt><dd>${fmtSize(items.reduce((n,v)=>n+v.size,0))}</dd><dt>Can pause</dt><dd>${items.filter(v=>M.eligible(v,'pause')).length}</dd></dl></section><section class="detail-card"><h3>Batch actions</h3><p>Remove drops entries from the live list and keeps downloaded files and history.</p></section></div>`;return;}const extra=t.multifile||t.protocol==='BitTorrent';if(!extra&&['files','connections'].includes(detailTab))detailTab='overview';const tabs=['overview',...(extra?['files','connections']:[]),'options'];let body='';if(detailTab==='overview'){const cards=[['Transfer',[['Speed',fmtSpeed(effectiveSpeed(t))],['Downloaded',fmtSize(t.size*t.progress/100)]]],['Progress',[['Total',fmtSize(t.size)],['Complete',Math.round(t.progress)+'%'],['ETA',eta(t)]]],['Network',[['Connections',t.connections],['Server',new URL(t.source).hostname]]],['General',[['Type',t.protocol],['Created',date(t.added)],['Completed',t.completed?date(t.completed):'—'],['Save path',t.folder]]]];body='<div class="detail-cards">'+cards.map(([name,fields])=>`<section class="detail-card"><h3>${name}</h3><dl>${fields.map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl></section>`).join('')+'</div>';}else if(detailTab==='options')body=`<div class="detail-options"><label>Download priority<select id="taskPriority"><option>Normal</option><option>High</option><option>Low</option></select></label><label>Per-task limit<input type="number" id="taskLimit" min="0" value="${t.limit||0}" aria-label="Per-task speed limit MB/s"> MB/s</label><span class="muted">Changes apply to this simulated transfer.</span></div>`;else body='<p>This sample has no additional multi-file or peer records.</p>';const errorCard=t.status==='Failed'?`<section class="error-card" role="alert"><div>${ico('close')}<div><strong>Download failed</strong><p>${esc(t.error.replace(/^HTTP \d+\s*·\s*/,''))}</p><span>${esc(t.error.match(/^HTTP \d+/)?.[0]||'Network error')}</span></div></div><button data-row-action="retry" data-id="${t.id}" class="secondary" ${engine!=='ready'?'disabled':''}>${ico('retry')}Retry</button></section>`:'';$('#detailsContent').innerHTML=actions+`<div class="details-file">${ico(M.fileIcon(t.name))}<div><strong>${esc(t.name)}</strong><span class="protocol">${t.protocol}</span></div></div>${errorCard}<label class="path-field"><input readonly aria-label="Save path" value="${esc(t.folder+'\\'+t.name)}"><button id="copyPath" title="Copy save path" aria-label="Copy save path">${ico('copy')}</button></label><div class="tabs" role="tablist" aria-label="Transfer detail sections">${tabs.map(tab=>`<button role="tab" data-detail-tab="${tab}" aria-selected="${tab===detailTab}">${tab[0].toUpperCase()+tab.slice(1)}</button>`).join('')}</div><div role="tabpanel">${body}</div>`;}
