function select(id,e={}){dismissContextMenu(false);contextMenuState.suppressDetails=false;const list=matches();if(e.shiftKey&&anchor!==null){const a=list.findIndex(t=>t.id===anchor),b=list.findIndex(t=>t.id===id);if(a>=0){if(!e.ctrlKey)selected.clear();list.slice(Math.min(a,b),Math.max(a,b)+1).forEach(t=>selected.add(t.id));}}else if(e.ctrlKey||e.metaKey||e.target?.type==='checkbox'){selected.has(id)?selected.delete(id):selected.add(id);anchor=id;}else{selected=new Set([id]);anchor=id;}render();const row=$(`#rows tr[data-id="${id}"]`);row?.focus({preventScroll:true});row?.scrollIntoView({block:'nearest',inline:'nearest'});announce(`${selected.size} selected`);}
function action(a,ids=new Set(selected)){if(['folder','file','copy'].includes(a)){const t=tasks.find(t=>ids.has(t.id));if(!t)return;if(a==='copy'){copy(t.source);return}if(a==='folder')showDialog('Saved location',`<p>${esc(t.name)}</p><label class="field">Saved to<input readonly value="${esc(t.folder+'\\'+t.name)}"></label><p>Folder opening is simulated in this prototype.</p>`,'<button id="dialogDone" class="secondary">Done</button>');else notify('Open file is simulated: '+t.name);return;}if(engine!=='ready'){notify('Reconnect the engine before changing transfers.');return;}if(a==='remove'||a==='delete'){confirmAction(a,ids);return;}const result=M.apply(tasks,ids,a);render();notify(`${result.changed} ${a==='pause'?'paused':a==='resume'?'resumed':'retrying'}${result.skipped?' · '+result.skipped+' unchanged':''}.`);closePopup();}
function confirmAction(a,ids){closePopup();showDialog(a==='delete'?'Delete files?':'Remove transfers?',`<p>${a==='delete'?'Delete the selected files and their sample records? This is a separate destructive action.':'Stop the selected transfers? Downloaded files and saved history will be kept.'}</p><p>${ids.size} selected · prototype only; no files on disk are changed.</p>`,`<button id="cancelDialog">Cancel</button><button id="confirmDestructive" class="danger secondary">${a==='delete'?'Delete files':'Remove'}</button>`);$('#confirmDestructive').onclick=()=>{if(a==='delete'){tasks=tasks.filter(t=>!ids.has(t.id));selected.clear();}else M.apply(tasks,ids,'remove');closeDialog();render();notify(a==='delete'?'Sample records deleted. No disk files were changed.':'Transfers stopped; files and history kept.');};}
function showDialog(title,body,footer){closePopup();dialogReturn=document.activeElement;$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=body;$('#dialogFoot').innerHTML=footer;$('#modalLayer').hidden=false;$('#application').inert=true;$('#dialogBody input:not([readonly]),#dialogBody textarea,#dialogFoot button,#closeDialog')?.focus();}
function closeDialog(){$('#modalLayer').hidden=true;$('#application').inert=false;dialogReturn?.focus?.();}
async function prefillAddFromClipboard(){const input=$('#addUrls');if(!input||input.value.trim()||!navigator.clipboard?.readText)return;try{const text=(await navigator.clipboard.readText()).trim(),lines=text.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);if(lines.length&&lines.every(v=>{try{return ['http:','https:'].includes(new URL(v).protocol);}catch{return false;}})){input.value=lines.join('\n');$('#addUrlsHint').textContent='Pasted from clipboard. Review the link before adding.';validateAdd();}}catch{/* Manual paste remains available when clipboard access is denied. */}}
function addDialog(){showDialog('Add download',`<form id="addForm"><label class="field">URL(s)<textarea id="addUrls" required aria-describedby="addUrlsHint addError" placeholder="https://example.com/file.zip&#10;One link per line" aria-label="Download URLs, one per line"></textarea><small id="addUrlsHint">Paste one or more HTTP or HTTPS links.</small><span id="addError" class="field-error" role="alert"></span></label><label class="field spaced-field">File name<input id="addName" placeholder="Use the filename from the link"><small id="nameHint">Available when adding one URL.</small></label><label class="field">Save folder<span class="input-button"><input id="addFolder" value="D:\\Downloads" required><button id="browseAddFolder" type="button" class="secondary">Browse…</button></span><small id="folderHint">Writable · 184 GB free</small></label><label class="toggle-row"><span><strong>Start paused</strong><small>Add to the queue without starting the transfer.</small></span><span class="toggle-switch"><input id="startPaused" type="checkbox" role="switch"><span aria-hidden="true"></span></span></label><details><summary>Advanced</summary><div class="advanced-fields"><label class="field">Referrer<input id="referrer" type="url" placeholder="https://example.com/"></label><label class="field">Cookies<textarea id="cookies" placeholder="name=value"></textarea><small>Sent only to this download’s server; never saved to history.</small></label><label class="field">Headers<textarea id="headers" placeholder="Header: value"></textarea></label></div></details></form>`,`<button id="cancelDialog" class="secondary">Cancel</button><button id="submitAdd" class="primary" disabled>Add download</button>`);$('#addUrls').focus();validateAdd();prefillAddFromClipboard();}
function validateAdd(){const urlsField=$('#addUrls');if(!urlsField)return false;let urls=[];let message='';try{urls=M.parseUrls(urlsField.value);}catch(e){message=urlsField.value.trim()?e.message:'';}$('#addError').textContent=message;$('#addUrls').classList.toggle('invalid',!!message);$('#submitAdd').disabled=!!message||!urls.length||!$('#addFolder').value.trim();$('#addName').disabled=urls.length!==1;$('#nameHint').textContent=urls.length>1?'Disabled because multiple URLs are being added.':'Available when adding one URL.';return !$('#submitAdd').disabled;}
function validateDefaultFolder(){const field=$('#defaultFolder'),hint=$('#defaultFolderHint');if(!field||!hint)return true;const valid=/^[A-Za-z]:\\[^<>:"|?*]*$/.test(field.value.trim());field.classList.toggle('invalid',!valid);hint.classList.toggle('field-error',!valid);hint.textContent=valid?'Writable · 184 GB free':'Enter a valid writable Windows folder, for example D:\\Downloads.';return valid;}
function validateMinimumSize(){const field=$('#minimumSize'),error=$('#minimumSizeError');if(!field||!error)return true;const value=Number(field.value),valid=field.value!==''&&Number.isInteger(value)&&value>=0;field.classList.toggle('invalid',!valid);error.textContent=valid?(value===0?'No minimum; files of every size can be captured.':''):'Enter a whole number of 0 or greater.';return valid;}
function submitAdd(){try{const urls=M.parseUrls($('#addUrls').value),folder=$('#addFolder').value.trim(),paused=$('#startPaused').checked;if(!folder)throw Error('Choose a save folder.');const created=M.additions(urls,{startId:Math.max(0,...tasks.map(t=>t.id))+1,folder,name:$('#addName').value,paused});tasks.push(...created);filter='All';history=false;search='';page='downloads';selected=new Set(created.map(t=>t.id));showDetails=true;closeDialog();render();notify(`${created.length} download${created.length===1?'':'s'} added${paused?' paused':''}.`,false,created.length===1?created[0].id:null);}catch(e){$('#addError').textContent=e.message;$('#addError').hidden=false;}}
function dismissContextMenu(restoreFocus=true){if(!contextMenuState.open)return;const rowId=contextMenuState.rowId,returnElement=contextMenuState.returnElement;contextMenuState.open=false;contextMenuState.rowId=null;contextMenuState.returnElement=null;const box=$('#popover');if(popupKind==='context'){box.hidden=true;box.innerHTML='';popupKind='';}if(restoreFocus){const target=rowId!=null?$(`#rows tr[data-id="${rowId}"]`):returnElement;if(target?.isConnected)target.focus({preventScroll:true});}}
function closePopup(restoreFocus=true){if(contextMenuState.open){dismissContextMenu(restoreFocus);return;}if(!$('#popover').hidden){$('#popover').hidden=true;$('#popover').innerHTML='';$('#popover').removeAttribute('role');$('#appMenuButton').setAttribute('aria-expanded','false');popupKind='';}}
function popup(html,anchorElement,kind='menu'){if(kind!=='context')dismissContextMenu(false);const box=$('#popover');box.innerHTML=html;box.hidden=false;popupKind=kind;const frame=$('#frame').getBoundingClientRect(),r=anchorElement?.getBoundingClientRect?.()||{left:frame.left+12,bottom:frame.top+64};box.style.left=Math.max(8,Math.min(r.left-frame.left,frame.width-box.offsetWidth-8))+'px';box.style.top=Math.max(8,Math.min(r.bottom-frame.top+4,frame.height-box.offsetHeight-8))+'px';box.querySelector('button:not(:disabled),input:not(:disabled),select:not(:disabled)')?.focus();}
function contextMenu(anchorElement,rowId=null){dismissContextMenu(false);contextMenuState.open=true;contextMenuState.rowId=rowId;contextMenuState.returnElement=anchorElement;const items=chosen(),single=items.length===1,t=items[0],stateActions=['pause','resume','retry'].filter(a=>items.some(v=>M.eligible(v,a))).map(a=>btn(a[0].toUpperCase()+a.slice(1),a,{pause:'pause',resume:'play',retry:'retry'}[a],engine!=='ready'?'disabled':'')).join('');popup(stateActions+btn('Open file','file','open',!single||t?.status!=='Completed'?'disabled':'')+btn('Open folder','folder','folder',!single?'disabled':'')+btn('Copy link','copy','copy',!single?'disabled':'')+'<hr>'+btn('Remove from list','remove','delete','class="danger" title="Keeps downloaded files and history"')+btn('Delete files from disk…','delete','delete','class="danger" title="Deletes saved files and the list entry"'),anchorElement,'context');}
function openRowContextMenu(id){dismissContextMenu(false);const detailsWasOpen=!$('#details').hidden;contextMenuState.suppressDetails=!detailsWasOpen;if(!selected.has(id)){selected=new Set([id]);anchor=id;render();}const row=$(`#rows tr[data-id="${id}"]`);contextMenu(row,id);}
function viewMenu(anchorElement){popup(`<div class="menu-heading">Row density</div><button data-density="compact">${density==='compact'?ico('check'):''}Compact · 32 px</button><button data-density="comfortable">${density==='comfortable'?ico('check'):''}Comfortable · 40 px</button><hr><button id="columnsMenu">${ico('columns')}Choose columns…</button><button id="toggleDetails">${ico('panel')}${showDetails?'Hide':'Show'} details panel</button><hr><button data-layout="fit">${layoutMode==='fit'?ico('check'):''}Fit available width</button><button data-layout="manual">${layoutMode==='manual'?ico('check'):''}Manual column widths</button><div class="menu-heading">Sort</div><button id="defaultSort">${sort==='default'?ico('check'):''}${history?'Newest history first':'Active first · newest'}</button>`,anchorElement,'view');}
function appMenu(anchorElement){popup(`<div class="menu-heading">Downloads</div><button id="appMenuNew">${ico('add')}New download</button><button id="appMenuHistory">${ico('history')}History</button><hr><button id="appMenuView">${ico('columns')}View options</button><button id="appMenuSettings">${ico('settings')}Settings</button><button id="appMenuAbout">${ico('info')}About AriaGUI</button>`,anchorElement,'app');$('#popover').setAttribute('role','menu');$$('#popover button').forEach(button=>button.setAttribute('role','menuitem'));$('#appMenuButton').setAttribute('aria-expanded','true');}
function columnsMenu(anchorElement){popup('<div class="menu-heading">Visible columns</div>'+columns.map(c=>`<label><input type="checkbox" data-column-toggle="${c.id}" ${columnsEnabled.has(c.id)?'checked':''} ${c.required?'disabled':''}>${c.label}${c.required?' (always visible)':''}</label>`).join('')+'<button id="doneColumns">Done</button>',anchorElement,'columns');}
function speedMenu(anchorElement){popup(['Unlimited','Standard','Reduced'].map(s=>`<button data-speed="${s}">${speedMode===s?ico('check'):''}${s}${s==='Standard'?' · 10 MB/s':s==='Reduced'?' · 2 MB/s':''}</button>`).join('')+'<hr><button id="customSpeed">Custom…</button>',anchorElement,'speed');}
function settingsBody(){const section=settingsSection;if(section==='Appearance')return `<div class="setting-row"><div><strong>Theme</strong><p>Choose the app color scheme.</p></div><select id="settingsTheme"><option value="dark">Dark</option><option value="light">Light</option><option value="contrast">High Contrast</option></select></div><div class="setting-row"><div><strong>Density</strong><p>Control the height of transfer rows.</p></div><select id="settingsDensity"><option value="compact">Compact · 32 px</option><option value="comfortable">Comfortable · 40 px</option></select></div><div class="setting-row"><div><strong>Typeface</strong><p>Used throughout the interface.</p></div><strong>Plus Jakarta Sans</strong></div>`;if(section==='Integration')return `<div class="integration-status"><span class="connection-dot ${integrationConnected?'connected':'disconnected'}"></span><div><strong>${integrationConnected?'Connected':'Not connected'}</strong><p>${integrationConnected?'Ready to receive downloads from your browser.':'The browser extension cannot send downloads to AriaGUI.'}</p></div><button id="extensionConnect" class="${integrationConnected?'secondary':'primary'}">${integrationConnected?'Disconnect':'Reconnect'}</button>${!integrationConnected?'<button id="installExtension" class="secondary">Install extension</button>':''}</div>${toggle('integrationToggle',integrationEnabled,'Capture browser downloads','Offer AriaGUI when supported files are downloaded.')}${toggle('altBypass',true,'Hold Alt to bypass capture','Keep a download in the browser while holding Alt when you click it.')}${toggle('sitePopupToggle',true,'Per-site control in extension popup','Let the extension popup turn capture on or off for the current site.')}<label class="setting-row"><div><strong>Minimum download size</strong><p>Numbers only. Set 0 to capture files of every size.</p></div><span class="unit-input"><input id="minimumSize" type="number" inputmode="numeric" min="0" step="1" value="10" aria-label="Minimum download size in MB"><span>MB</span></span></label><span id="minimumSizeError" class="setting-error" role="alert"></span><div class="privacy-note">${ico('info')}<span>Cookies are passed to this download only and aren’t saved.</span></div><label class="field"><strong>File types</strong><input id="fileTypes" value="zip, iso, exe, msi, mp4"><small>Comma-separated extensions handled by the browser extension.</small></label><label class="field"><strong>Site exclusions</strong><textarea id="siteExclusions" placeholder="One domain per line">bank.example.com</textarea><small>Downloads from these sites remain in the browser.</small></label>${toggle('protocolHandler',true,'Protocol handler','Open aria2:// links in AriaGUI.')}`;if(section==='Downloads')return `<label class="setting-row"><div><strong>Simultaneous downloads</strong><p>Additional transfers wait in the queue. Engine restart required.</p></div><input type="number" id="concurrency" data-restart-setting min="1" max="16" value="5"></label><label class="field"><strong>Default save folder</strong><span class="input-button"><input id="defaultFolder" value="D:\\Downloads"><button id="browseDefaultFolder" type="button" class="secondary">Browse…</button></span><small id="defaultFolderHint">Writable · 184 GB free</small></label><div class="setting-row"><div><strong>Speed mode</strong><p>Applies to all active transfers.</p></div><button id="settingsSpeed" class="secondary">${esc(speedMode)}</button></div>`;if(section==='Network')return `<label class="field"><strong>Proxy</strong><input id="proxySetting" data-restart-setting placeholder="Optional proxy address"><small>Used by the aria2 engine after restart.</small></label><label class="setting-row"><div><strong>Retry count</strong><p>Attempts before a transfer is marked failed.</p></div><input id="retryCount" data-restart-setting type="number" value="5" min="0"></label>`;if(section==='BitTorrent')return `${toggle('dhtSetting',true,'Distributed hash table','Find peers without relying only on trackers.')}<p class="muted">BitTorrent network changes apply after an engine restart.</p>`;if(section==='Advanced')return `<p class="muted">Engine controls are simulated.</p><button id="simulateEngineFailure" class="secondary">Preview engine failure</button>`;if(section==='About')return '<p>AriaGUI workspace concept</p><p class="muted">Microsoft Fluent System Icons · MIT license.<br>All transfers and engine events are simulated.</p>';return `${toggle('launchAtSignIn',false,'Launch at sign-in','Start AriaGUI when you sign in to Windows.')}${toggle('keepRunning',true,'Keep running in the notification area','Closing the window keeps downloads going in the background.')}`;}
function renderSettings(){const sections=['General','Appearance','Downloads','Network','BitTorrent','Integration','Advanced','About'];$('#settingsNav').innerHTML=sections.map(s=>`<button id="settingsTab${s}" role="tab" aria-controls="settingsPane" aria-selected="${settingsSection===s}" tabindex="${settingsSection===s?'0':'-1'}" data-settings="${s}" class="${settingsSection===s?'active':''}">${s}</button>`).join('');$('#settingsPane').setAttribute('aria-labelledby',`settingsTab${settingsSection}`);$('#settingsPane').innerHTML=`<div class="settings-pane-inner"><div class="settings-title"><h2>${settingsSection}</h2><span id="settingsSaved" class="saved-indicator" role="status"></span></div>${settingsRestartRequired?`<div class="settings-restart info-bar">${ico('info')}<span class="message">These changes apply after the download engine restarts.</span><button id="restartFromSettings" class="secondary">Restart engine</button></div>`:''}${settingsBody()}${!['About','Advanced'].includes(settingsSection)?'<button id="resetSettings" class="reset-link">Reset this section to defaults</button>':''}</div>`;if($('#settingsTheme'))$('#settingsTheme').value=$('#frame').dataset.theme;if($('#settingsDensity'))$('#settingsDensity').value=density;}
function markSettingsSaved(restart=false){settingsRestartRequired||=restart;if(restart)renderSettings();const saved=$('#settingsSaved');if(saved){saved.textContent='Saved';clearTimeout(settingsSavedTimer);settingsSavedTimer=setTimeout(()=>{if($('#settingsSaved'))$('#settingsSaved').textContent='';},1800);}}
function renderNotifications(){$('#notifications').innerHTML=`<article class="notice-card"><strong>Session restored</strong><p>${esc(notification)}</p><button data-page="downloads" class="secondary">View downloads</button></article>`;}
function setDensity(v){density=v;$('#frame').style.setProperty('--row-height',v==='compact'?'32px':'40px');closePopup();render();}
function setTheme(v){$('#frame').dataset.theme=v;$('#themePicker').value=v;}
function copy(text){if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(()=>notify('Copied.')).catch(()=>showCopy(text));else showCopy(text);}
function showCopy(text){showDialog('Copy value',`<label class="field">Value<input id="copyValue" readonly value="${esc(text)}"></label><p>Press Ctrl+C to copy.</p>`,'<button id="dialogDone" class="secondary">Done</button>');$('#copyValue').select();}
function fitViewportPreview(){const stage=$('.stage'),frame=$('#frame');frame.style.transform='';frame.style.marginRight='';frame.style.marginBottom='';stage.classList.remove('scaled-preview');if(previewViewport==='auto')return;const[w,h]=previewViewport.split('x').map(Number),availableWidth=Math.max(0,stage.clientWidth-24),availableHeight=Math.max(0,stage.clientHeight-24),scale=Math.min(1,availableWidth/w||1,availableHeight/h||1);if(scale<1){frame.style.transform=`scale(${scale})`;frame.style.transformOrigin='top left';frame.style.marginRight=`${w*(scale-1)}px`;frame.style.marginBottom=`${h*(scale-1)}px`;stage.classList.add('scaled-preview');}frame.dataset.previewScale=String(scale);}
function viewport(v){dismissContextMenu(true);previewViewport=v;if(v==='auto'){$('#frame').style.width='calc(100vw - 24px)';$('#frame').style.height='calc(100dvh - 80px)';}else{const[w,h]=v.split('x');$('#frame').style.width=w+'px';$('#frame').style.height=h+'px';}$('#viewportPicker').value=v;fitViewportPreview();setTimeout(()=>{fitViewportPreview();ensureSelectionVisible();},0);}
function state(s){clearTimeout(reconnectTimer);closePopup(false);contextMenuState.suppressDetails=false;closeDialog();tasks=M.seed();selected.clear();anchor=null;filter='All';history=false;search='';sort='default';page='downloads';engine='ready';showDetails=true;detailTab='overview';hideToast();handoffId=null;if(s==='empty')tasks=[];if(s==='noresults')search='no-such-file';if(s==='failed'){filter='Failed';selected=new Set([14]);}if(s==='reconnecting'){engine='reconnecting';reconnectTimer=setTimeout(()=>{if(engine==='reconnecting'){engine='failed';render();}},7000);}if(s==='enginefailed')engine='failed';if(s==='multiselect')selected=new Set([1,2,3]);if(s==='settings'||s==='integration'||s==='disconnected'){page='settings';settingsSection=s==='settings'?'General':'Integration';integrationConnected=s!=='disconnected';}if(['narrow','regular','wide'].includes(s))viewport({narrow:'560x420',regular:'1280x800',wide:'1920x1080'}[s]);render();if(s==='add')addDialog();if(s==='handoff'){const t=M.additions([new URL('https://example.com/file.zip')],{startId:25,folder:'D:\\Downloads',paused:true})[0];tasks.push(t);handoffId=t.id;render();notify('Added paused from browser: file.zip',true,t.id);}$('#statePicker').value=s;}
function restartEngine(){clearTimeout(reconnectTimer);engine='reconnecting';render();reconnectTimer=setTimeout(()=>{engine='ready';render();notify('Engine restarted. Transfer states refreshed.');},1200);}
function resizeCommit(kind,value){if(kind==='sidebar'){sidebarWidth=Math.max(160,Math.min(260,value));$('#frame').style.setProperty('--sidebar-width',sidebarWidth+'px');$('#sidebarGrip').setAttribute('aria-valuenow',sidebarWidth);announce('Sidebar width '+sidebarWidth+' pixels');}else if(kind==='details'){if(frameWidth<1100){detailsHeight=Math.max(100,Math.min(500,value));$('#frame').style.setProperty('--details-height',detailsHeight+'px');$('#detailsGrip').setAttribute('aria-valuenow',detailsHeight);announce('Details height '+detailsHeight+' pixels');}else{detailsWidth=Math.max(280,Math.min(600,value));$('#frame').style.setProperty('--details-width',detailsWidth+'px');$('#detailsGrip').setAttribute('aria-valuenow',detailsWidth);announce('Details width '+detailsWidth+' pixels');}}else{const c=columns.find(c=>c.id===kind);c.width=Math.max(c.required?120:70,Math.min(600,value));layoutMode='manual';renderTable();announce(c.label+' column width '+c.width+' pixels');}}
document.addEventListener('click',e=>{const b=e.target.closest?.('button');if(b?.dataset.action){action(b.dataset.action);return;}if(b?.dataset.rowAction){const id=+b.dataset.id,a=b.dataset.rowAction;if(a==='menu')openRowContextMenu(id);else action(a,new Set([id]));return;}if(b?.dataset.page){page=b.dataset.page;closePopup();render();return;}if(b?.dataset.filter){setFilter(b.dataset.filter);return;}if(b?.dataset.sort){if(sort===b.dataset.sort)direction*=-1;else{sort=b.dataset.sort;direction=1;}renderTable();return;}if(b?.dataset.detailTab){detailTab=b.dataset.detailTab;renderDetails();return;}if(b?.dataset.settings){settingsSection=b.dataset.settings;renderSettings();return;}if(b?.dataset.density){setDensity(b.dataset.density);return;}if(b?.dataset.layout){layoutMode=b.dataset.layout;closePopup();renderTable();return;}if(b?.dataset.speed){speedMode=b.dataset.speed;speedLimit=speedMode==='Standard'?10:speedMode==='Reduced'?2:0;closePopup();renderFooter();notify('Speed limit: '+speedMode);return;}const row=e.target.closest?.('#rows tr');if(row&&!e.target.closest?.('button')){select(+row.dataset.id,e);return;}if(!e.target.closest('#popover')&&!['viewButton','moreButton','filtersButton','speedButton','settingsSpeed','engineButton','detailsMore'].includes(b?.id))closePopup();switch(b?.id){case'newButton':case'emptyAdd':addDialog();break;case'submitAdd':if(validateAdd())submitAdd();break;case'viewButton':viewMenu(b);break;case'moreButton':contextMenu(b);break;case'detailsMore':popup(btn('Copy URL','copy','copy')+btn('Remove from list','remove','delete','class="danger"'),b,'details');break;case'filtersButton':popup('<div class="menu-heading">Filters</div>'+M.states.map(s=>`<button data-filter="${s}">${ico(stateIcon(s))}${M.label(s)} · ${tasks.filter(t=>s==='All'||t.status===s).length}</button>`).join('')+'<hr><button id="historyMenu">History</button><button data-page="settings">Settings</button><button data-page="notifications">Notifications</button>',b,'filters');break;case'historyButton':case'historyMenu':setFilter('All',true);notify('History contains completed, failed and stopped records.');break;case'clearSelection':dismissContextMenu(false);contextMenuState.suppressDetails=false;selected.clear();render();break;case'pauseAllButton':{const a=b.dataset.bulkAction||'pause';action(a,new Set(matches().filter(t=>M.eligible(t,a)).map(t=>t.id)));break;}case'clearSearch':dismissContextMenu(false);contextMenuState.suppressDetails=false;search='';filter='All';history=false;selected.clear();render();break;case'columnsMenu':columnsMenu($('#viewButton'));break;case'doneColumns':closePopup();$('#viewButton').focus();break;case'toggleDetails':dismissContextMenu(true);contextMenuState.suppressDetails=false;showDetails=!showDetails;closePopup();renderDetails();break;case'collapseDetails':dismissContextMenu(true);contextMenuState.suppressDetails=false;showDetails=false;renderDetails();break;case'defaultSort':sort='default';closePopup();renderTable();break;case'speedButton':case'settingsSpeed':speedMenu(b);break;case'customSpeed':showDialog('Custom speed limit','<label class="field">Download limit (MB/s)<input id="customLimit" type="number" min="0.1" step="0.1" value="5"></label>','<button id="cancelDialog" class="secondary">Cancel</button><button id="saveCustomSpeed" class="primary">Apply limit</button>');break;case'saveCustomSpeed':{const n=+$('#customLimit').value;if(!Number.isFinite(n)||n<=0){$('#customLimit').focus();return;}speedMode='Custom';speedLimit=n;closeDialog();renderFooter();break;}case'footerCounts':setFilter('ActiveQueue');break;case'engineButton':popup(`<div class="engine-flyout"><div class="engine-flyout-title"><strong>${engine==='ready'?'Engine ready':engine==='failed'?'Engine stopped':'Reconnecting…'}</strong><button id="closeEngineFlyout" title="Close" aria-label="Close">${ico('close')}</button></div><p>${engine==='ready'?'aria2 is connected and accepting commands.':'Transfer states may be out of date.'}</p>${engine==='failed'?'<button id="restartEngine" class="primary">Restart engine</button>':''}</div>`,b,'engine');break;case'closeEngineFlyout':closePopup();break;case'restartEngine':case'restartFromSettings':settingsRestartRequired=false;restartEngine();break;case'closeDialog':case'cancelDialog':case'dialogDone':closeDialog();break;case'browseAddFolder':$('#addFolder').value='D:\\Downloads';$('#folderHint').textContent='Writable · 184 GB free';validateAdd();break;case'browseDefaultFolder':$('#defaultFolder').value='D:\\Downloads';validateDefaultFolder();markSettingsSaved();break;case'resetSettings':settingsRestartRequired=false;renderSettings();markSettingsSaved();break;case'copyPath':{const t=chosen()[0];copy(t.folder+'\\'+t.name);break;}case'undoHandoff':tasks=tasks.filter(t=>t.id!==handoffId);selected.delete(handoffId);handoffId=null;hideToast();render();announce('Browser handoff undone.');break;case'showToastItem':{const id=toastItemId;if(id!=null&&tasks.some(t=>t.id===id)){page='downloads';filter='All';history=false;search='';selected=new Set([id]);showDetails=true;hideToast();render();setTimeout(ensureSelectionVisible,0);}break;}case'dismissToast':hideToast();break;case'extensionConnect':integrationConnected=!integrationConnected;renderSettings();markSettingsSaved();break;case'installExtension':notify('Extension store handoff is simulated.');break;case'simulateEngineFailure':page='downloads';engine='failed';render();break;}});
document.addEventListener('click',e=>{if(e.target.closest?.('[data-page="downloads"]')){history=false;filter='All';}},true);
document.addEventListener('click',e=>{
  const button=e.target.closest?.('button');
  if(!button)return;
  if(button.dataset.settings){$(`#settingsTab${settingsSection}`)?.focus();return;}
  switch(button.id){
    case'appMenuButton':appMenu(button);break;
    case'appMenuNew':closePopup();addDialog();break;
    case'appMenuHistory':closePopup();setFilter('All',true);break;
    case'appMenuView':closePopup();page='downloads';render();viewMenu($('#viewButton'));break;
    case'appMenuSettings':closePopup();page='settings';render();$('#settingsNav [aria-selected="true"]')?.focus();break;
    case'appMenuAbout':closePopup();settingsSection='About';page='settings';render();$('#settingsNav [aria-selected="true"]')?.focus();break;
  }
});
$('#settingsNav').addEventListener('keydown',e=>{
  if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;
  const tabs=Array.from($('#settingsNav').querySelectorAll('[role="tab"]'));
  const index=tabs.indexOf(document.activeElement);
  if(index<0)return;
  e.preventDefault();
  const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;
  settingsSection=tabs[next].dataset.settings;
  renderSettings();
  $(`#settingsTab${settingsSection}`).focus();
});
$('#search').addEventListener('input',e=>{dismissContextMenu(false);contextMenuState.suppressDetails=false;search=e.target.value;selected.clear();render();$('#search').focus();});
document.addEventListener('input',e=>{if(['addUrls','addFolder'].includes(e.target.id))validateAdd();if(e.target.id==='defaultFolder'&&!validateDefaultFolder())return;if(e.target.id==='minimumSize'&&!validateMinimumSize())return;if(e.target.closest('#settingsPane'))markSettingsSaved(e.target.hasAttribute('data-restart-setting'));});
document.addEventListener('submit',e=>{if(e.target.id==='addForm'){e.preventDefault();submitAdd();}});
document.addEventListener('change',e=>{if(e.target.id==='selectAll'){dismissContextMenu(false);contextMenuState.suppressDetails=false;selected=new Set(e.target.checked?matches().map(t=>t.id):[]);render();announce(selected.size+' selected');}if(e.target.dataset.columnToggle){e.target.checked?columnsEnabled.add(e.target.dataset.columnToggle):columnsEnabled.delete(e.target.dataset.columnToggle);renderTable();}if(e.target.id==='settingsTheme')setTheme(e.target.value);if(e.target.id==='settingsDensity')setDensity(e.target.value);if(e.target.id==='integrationToggle')integrationEnabled=e.target.checked;if(e.target.matches('[role="switch"]')){const label=$(`#${e.target.id}State`);if(label)label.textContent=e.target.checked?'On':'Off';}if(e.target.closest('#settingsPane'))markSettingsSaved(e.target.hasAttribute('data-restart-setting'));if(e.target.id==='taskLimit'){chosen()[0].limit=+e.target.value;notify('Per-task sample limit updated.');}});
$('#statePicker').addEventListener('change',e=>state(e.target.value));$('#viewportPicker').addEventListener('change',e=>viewport(e.target.value));$('#themePicker').addEventListener('change',e=>setTheme(e.target.value));$('#textPicker').addEventListener('change',e=>$('#frame').dataset.textSize=e.target.value);
document.addEventListener('contextmenu',e=>{if(contextMenuState.open)dismissContextMenu(false);const header=e.target.closest('#transferTable th');if(header){e.preventDefault();columnsMenu(header);return;}const row=e.target.closest('#rows tr[data-id]');if(row){e.preventDefault();openRowContextMenu(+row.dataset.id);}});
document.addEventListener('pointerdown',e=>{if(contextMenuState.open&&!e.target.closest('#popover'))dismissContextMenu(e.button!==2);},true);
document.addEventListener('scroll',()=>dismissContextMenu(true),true);
window.addEventListener('resize',()=>{dismissContextMenu(true);fitViewportPreview();});
window.addEventListener('blur',()=>dismissContextMenu(true));
$('#toast').addEventListener('mouseenter',pauseToast);$('#toast').addEventListener('mouseleave',resumeToast);$('#toast').addEventListener('focusin',pauseToast);$('#toast').addEventListener('focusout',e=>{if(!$('#toast').contains(e.relatedTarget))resumeToast();});
document.addEventListener('keydown',e=>{if(!$('#modalLayer').hidden){if(e.key==='Escape'){e.preventDefault();closeDialog();}if(e.key==='Tab'){const els=$$('#dialog button:not(:disabled),#dialog input:not(:disabled),#dialog textarea,#dialog select,#dialog summary').filter(el=>el.getClientRects().length);if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus();}}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'&&$('#addForm')){e.preventDefault();submitAdd();}return;}if(e.key==='Escape'){closePopup();if(document.activeElement===$('#search')){search='';render();}}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='f'){e.preventDefault();page='downloads';render();$('#search').focus();}const grip=e.target.closest?.('[role=separator]');if(grip&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const delta=['ArrowRight','ArrowDown'].includes(e.key)?8:-8;const kind=grip.id==='sidebarGrip'?'sidebar':grip.id==='detailsGrip'?'details':grip.dataset.resizeColumn;const base=kind==='sidebar'?sidebarWidth:kind==='details'?(frameWidth<1100?detailsHeight:detailsWidth):columns.find(c=>c.id===kind).width;resizeCommit(kind,base+delta);return;}if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='a'&&page==='downloads'&&$('#application').contains(e.target)){e.preventDefault();selected=new Set(matches().map(t=>t.id));render();$('#rows tr')?.focus();return;}const row=e.target.closest?.('#rows tr');if(row){if(e.key===' '&&!e.target.closest?.('button')){e.preventDefault();if(!selected.has(+row.dataset.id))selected=new Set([+row.dataset.id]);action(chosen().some(t=>M.eligible(t,'pause'))?'pause':'resume');}if(e.key==='Delete'){e.preventDefault();if(!selected.size)selected=new Set([+row.dataset.id]);action('remove');}if(e.key==='Enter'&&!e.target.closest?.('button')){e.preventDefault();selected=new Set([+row.dataset.id]);showDetails=true;render();$('#detailsContent button:not(:disabled)')?.focus();}if(['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const list=matches(),index=list.findIndex(t=>t.id===+row.dataset.id),next=list[Math.max(0,Math.min(list.length-1,index+(e.key==='ArrowDown'?1:-1)))];select(next.id,{shiftKey:e.shiftKey});$(`#rows tr[data-id="${next.id}"]`)?.scrollIntoView({block:'nearest'});}}if(!$('#popover').hidden&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();const els=$$('#popover button:not(:disabled),#popover input:not(:disabled)'),i=els.indexOf(document.activeElement);els[(i+(e.key==='ArrowDown'?1:-1)+els.length)%els.length]?.focus();}});
document.addEventListener('pointerdown',e=>{const grip=e.target.closest?.('[role=separator]');if(!grip)return;e.preventDefault();const kind=grip.id==='sidebarGrip'?'sidebar':grip.id==='detailsGrip'?'details':grip.dataset.resizeColumn;const start=kind==='details'&&frameWidth<1100?e.clientY:e.clientX;const original=kind==='sidebar'?sidebarWidth:kind==='details'?(frameWidth<1100?detailsHeight:detailsWidth):columns.find(c=>c.id===kind).width;const move=ev=>{const point=kind==='details'&&frameWidth<1100?ev.clientY:ev.clientX;resizeCommit(kind,original+(point-start)*(kind==='details'?-1:1));};const up=()=>{document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);};document.addEventListener('pointermove',move);document.addEventListener('pointerup',up);});
$('#frame').addEventListener('dragover',e=>e.preventDefault());$('#frame').addEventListener('drop',e=>{e.preventDefault();if(e.dataTransfer.files.length){notify('File drop received. This HTTP prototype accepts direct URLs; file imports are not implemented.');return;}const text=e.dataTransfer.getData('text/uri-list')||e.dataTransfer.getData('text/plain');if(text){addDialog();$('#addUrls').value=text;}});
new ResizeObserver(()=>{dismissContextMenu(true);frameWidth=$('#frame').clientWidth;tableWidth=$('#tableRegion').clientWidth||frameWidth;$('#detailsGrip').setAttribute('aria-orientation',frameWidth<1100?'horizontal':'vertical');$('#detailsGrip').setAttribute('aria-label',frameWidth<1100?'Details panel height':'Details panel width');$('#detailsGrip').setAttribute('aria-valuenow',frameWidth<1100?detailsHeight:detailsWidth);renderTable();}).observe($('#frame'));
new ResizeObserver(()=>{dismissContextMenu(true);const w=$('#tableRegion').clientWidth;if(w&&w!==tableWidth){tableWidth=w;renderTable();}}).observe($('#tableRegion'));
setInterval(()=>{if(engine!=='ready')return;const before=tasks.filter(t=>t.status==='Completed').length;if(M.advance(tasks)){renderTable();renderActions();if(!$('#detailsContent').contains(document.activeElement)||!['INPUT','SELECT'].includes(document.activeElement.tagName))renderDetails();renderFooter();if(tasks.filter(t=>t.status==='Completed').length>before){newestFinished=tasks.filter(t=>t.completed).sort((a,b)=>b.completed-a.completed)[0];notify('Download complete: '+newestFinished.name,false,newestFinished.id);}}},700);
window.AriaPrototype={state,viewport,getSnapshot:()=>({tasks:structuredClone(tasks),selected:[...selected],filter,history,search,page,engine,density,layoutMode,showDetails,columns:[...columnsEnabled],frameWidth,tableWidth,speedMode,speedLimit,previewViewport,previewScale:+($('#frame').dataset.previewScale||1),contextMenu:{open:contextMenuState.open,rowId:contextMenuState.rowId,suppressDetails:contextMenuState.suppressDetails}})};
render();
